{
  "answer": "Acme protects personal information by taking reasonable steps to guard it against misuse, interference, loss, and unauthorised access, modification, or disclosure, with specific technical and organisational controls detailed in its internal policies. Across all production systems, personal information is encrypted at rest using AES-256 and in transit using TLS 1.2 or higher. Access to systems containing customer personal information is strictly restricted to authorized employees on a least-privilege basis and is reviewed quarterly. Additionally, company-issued laptops and mobile devices are encrypted and managed via a mobile device management platform that enforces automatic locking, remote wipe capabilities, and mandatory security updates.",
  "citations": [
    {
      "clause_id": "acme/privacy-policy:v1:5/1",
      "quote": "We take reasonable steps to protect the personal information we hold from misuse, interference, loss, and unauthorised access, modification or disclosure."
    },
    {
      "clause_id": "acme/data-security-policy:v1:1/1",
      "quote": "Personal information is encrypted at rest using AES-256 and in transit using TLS 1.2 or higher, across all production systems."
    },
    {
      "clause_id": "acme/data-security-policy:v1:2/1",
      "quote": "Access to systems holding customer personal information is restricted to employees whose role requires it, granted on a least-privilege basis and reviewed quarterly by IT Security."
    },
    {
      "clause_id": "acme/employee-policy:v1:3/1",
      "quote": "Company-issued laptops and mobile devices are encrypted and enrolled in our mobile device management platform, which enforces automatic locking, remote wipe capability, and mandatory security updates."
    }
  ]
}

{
  "answer": "No, Acme does not sell customer data. According to its policies, Acme only discloses personal information to its logistics partners, payment provider, and IT service providers solely to the extent necessary for them to provide services to Acme. Furthermore, Acme does not disclose personal information to any third party for their own direct marketing unless the customer has provided opt-in consent.",
  "citations": [
    {
      "clause_id": "acme/privacy-policy:v1:3/3",
      "quote": "We disclose personal information to our logistics partners, our payment provider, and our IT service providers, solely to the extent necessary for them to provide services to us."
    },
    {
      "clause_id": "acme/privacy-policy:v1:3/2",
      "quote": "We do not use your personal information for direct marketing, and we do not disclose it to any third party for that third party's own direct marketing, unless you have given us your opt-in consent."
    }
  ]
}

